import{gt as e,nt as t,o as n,rt as r}from"./chunks/framework.CTZrU_RR.js";import"./chunks/assets.Dm7JhnKk.js";var i=JSON.parse('{"title":"DevTools in nuxt-i18n-micro","description":"Built-in DevTools for managing translations.","frontmatter":{"title":"DevTools in `nuxt-i18n-micro`","description":"Built-in DevTools for managing translations.","outline":"deep"},"headers":[],"relativePath":"guide/devtools.md","filePath":"guide/devtools.md","lastUpdated":1785931233000}'),a={name:`guide/devtools.md`};function o(n,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[r(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /nuxt-i18n-micro/guide/devtools.md for this page in Markdown format</div><h1 id="🛠️-devtools-in-nuxt-i18n-micro" tabindex="-1">🛠️ DevTools in <code>nuxt-i18n-micro</code> <a class="header-anchor" href="#🛠️-devtools-in-nuxt-i18n-micro" aria-label="Permalink to “🛠️ DevTools in nuxt-i18n-micro”">​</a></h1><h2 id="vue-devtools-browser-extension" tabindex="-1">Vue DevTools (browser extension) <a class="header-anchor" href="#vue-devtools-browser-extension" aria-label="Permalink to “Vue DevTools (browser extension)”">​</a></h2><p>In development, the module can register a <strong>Vue DevTools</strong> custom inspector and timeline via <code>@vue/devtools-api</code>. This is separate from the Nuxt DevTools tab below.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Best for</th></tr></thead><tbody><tr><td><strong>Vue DevTools</strong></td><td>Live locale, in-memory translation cache, <code>$t</code> timeline (<code>debug: true</code>), missing-key events</td></tr><tr><td><strong>Nuxt DevTools tab</strong></td><td>Editing JSON files on disk, config overview, import/export</td></tr></tbody></table><p>The vue-devtools plugin is registered only during <code>nuxt dev</code> (not in production builds). Dev-only bridge state in the main plugin is stripped by <code>import.meta.dev</code> dead-code elimination.</p><p>Disable the browser integration while keeping the Nuxt tab:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> default</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> defineNuxtConfig</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  i18n: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    vueDevtools: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><p>Verbose <code>$t</code> timeline events require <code>debug: true</code>.</p><hr><h2 id="📖-what-is-nuxt-devtools" tabindex="-1">📖 What Is Nuxt DevTools? <a class="header-anchor" href="#📖-what-is-nuxt-devtools" aria-label="Permalink to “📖 What Is Nuxt DevTools?”">​</a></h2><p>DevTools is a powerful development assistant seamlessly integrated into the <code>nuxt-i18n-micro</code> module. It provides an intuitive interface for managing localization and translation tasks, making your workflow faster and more efficient. Designed for developers who value convenience, Nuxt DevTools bridges the gap between coding and runtime management.</p><p><img src="/nuxt-i18n-micro/devtools.png" alt="DevTools"></p><h2 id="🌟-key-features-of-devtools-in-nuxt-i18n-micro" tabindex="-1">🌟 Key Features of DevTools in <code>nuxt-i18n-micro</code> <a class="header-anchor" href="#🌟-key-features-of-devtools-in-nuxt-i18n-micro" aria-label="Permalink to “🌟 Key Features of DevTools in nuxt-i18n-micro”">​</a></h2><h3 id="_1-locale-management" tabindex="-1">1. <strong>Locale Management</strong> <a class="header-anchor" href="#_1-locale-management" aria-label="Permalink to “1. Locale Management”">​</a></h3><p>Effortlessly browse, select, and manage locales in your application. Whether you’re working with a single language or multiple, DevTools provides a centralized hub for handling all localization settings.</p><h3 id="_2-translation-editing" tabindex="-1">2. <strong>Translation Editing</strong> <a class="header-anchor" href="#_2-translation-editing" aria-label="Permalink to “2. Translation Editing”">​</a></h3><p>Edit translation files directly through an integrated JSON editor. This eliminates the need for external tools, allowing real-time updates and changes without interrupting your workflow.</p><h3 id="_3-file-import-and-export" tabindex="-1">3. <strong>File Import and Export</strong> <a class="header-anchor" href="#_3-file-import-and-export" aria-label="Permalink to “3. File Import and Export”">​</a></h3><p>Simplify the process of managing translation files:</p><ul><li><strong>Export</strong>: Save translations as a JSON file for backups or external use.</li><li><strong>Import</strong>: Load updated translation files into the project to keep content up-to-date.</li></ul><h3 id="_4-real-time-previews" tabindex="-1">4. <strong>Real-Time Previews</strong> <a class="header-anchor" href="#_4-real-time-previews" aria-label="Permalink to “4. Real-Time Previews”">​</a></h3><p>View changes immediately within the development environment. This feature ensures translations and configurations are accurate before going live.</p><h3 id="_5-seamless-nuxt-integration" tabindex="-1">5. <strong>Seamless Nuxt Integration</strong> <a class="header-anchor" href="#_5-seamless-nuxt-integration" aria-label="Permalink to “5. Seamless Nuxt Integration”">​</a></h3><p>DevTools works natively with <code>nuxt-i18n-micro</code>, enhancing its capabilities without requiring additional setup. It adapts to your localization needs while maintaining Nuxt&#39;s modular and flexible structure.</p><hr><h2 id="🛠️-why-use-devtools" tabindex="-1">🛠️ Why Use DevTools? <a class="header-anchor" href="#🛠️-why-use-devtools" aria-label="Permalink to “🛠️ Why Use DevTools?”">​</a></h2><p>Nuxt DevTools is an indispensable addition for projects requiring localization. It helps developers by:</p><ul><li><strong>Saving Time</strong>: Automates repetitive tasks like file management and format validation.</li><li><strong>Reducing Errors</strong>: Provides a safe, intuitive environment for editing translations.</li><li><strong>Improving Collaboration</strong>: Enables non-developers to manage translations easily.</li><li><strong>Streamlining Workflows</strong>: Consolidates multiple localization tasks into a single interface.</li></ul><hr><h2 id="🚀-take-control-of-localization" tabindex="-1">🚀 Take Control of Localization <a class="header-anchor" href="#🚀-take-control-of-localization" aria-label="Permalink to “🚀 Take Control of Localization”">​</a></h2><p>With Nuxt DevTools integrated into <code>nuxt-i18n-micro</code>, managing multilingual applications becomes straightforward and efficient. Whether you&#39;re fine-tuning translations or adding new locales, DevTools equips you with the tools needed to deliver polished, user-friendly experiences.</p>`,32)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};